// Menu stores the information required for a standard menu.
// A menu can pop down from a MainMenu or could be a pop out menu.
type Menu struct {
	Label string
	Items []*MenuItem
}

// NewMenu creates a new menu given the specified label (to show in a MainMenu) and list of items to display.
func NewMenu(label string, items ...*MenuItem) *Menu {
	return &Menu{Label: label, Items: items}
}

// Refresh triggers a refresh of this menu in all windows where it is currently displayed.
// This should be called when menu items are changed or when icons/shortcuts are updated.
//
// Since: 2.5
func (m *Menu) Refresh() {
	// The actual refresh logic will be implemented by the driver/internal code
	// This method signature allows apps to call it when they update menu items
	for _, win := range CurrentApp().Driver().AllWindows() {
		if win.MainMenu() != nil {
			for _, menu := range win.MainMenu().Items {
				if menu == m {
					win.SetMainMenu(win.MainMenu()) // Trigger refresh
					return
				}
			}
		}
	}
}

