package theme

import (
	"encoding/json"
	"image/color"
	"io"

	"fyne.io/fyne/v2"
)

// jsonTheme represents a theme that can be loaded from JSON
type jsonTheme struct {
	colors map[fyne.ThemeColorName]map[fyne.ThemeVariant]color.Color
	sizes  map[fyne.ThemeSizeName]float32
	fonts  map[fyne.TextStyle]fyne.Resource
}

// jsonThemeData represents the JSON structure for theme data
type jsonThemeData struct {
	Colors map[string]map[string]string `json:"colors"` // colorName -> variant -> hex
	Sizes  map[string]float32           `json:"sizes"`  // sizeName -> value
}

// Color returns the theme color for the specified color name and variant
func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	if t.colors == nil {
		return DefaultTheme().Color(name, variant)
	}

	if variants, ok := t.colors[name]; ok {
