func parseHexColor(hex string) (color.Color, error) {
	var r, g, b uint8
	var a uint8 = 255

	// Remove leading # if present
	if len(hex) > 0 && hex[0] == '#' {
		hex = hex[1:]
	}

	// Parse different hex formats
	switch len(hex) {
	case 6: // RGB
		_, err := parseHex(hex, &r, &g, &b)
		if err != nil {
			return nil, err
		}
