	for i, v := range values {
		val := uint8(0)
		for j := 0; j < 2; j++ {
			idx := i*2 + j
			if idx >= len(hex) {
				return i, json.Unmarshal([]byte(`"hex too short"`), nil)
			}

			c := hex[idx]
			var digit uint8
			switch {
			case c >= '0' && c <= '9':
				digit = c - '0'
			case c >= 'a' && c <= 'f':
				digit = c - 'a' + 10
			case c >= 'A' && c <= 'F':
				digit = c - 'A' + 10
			default:
				return i, json.Unmarshal([]byte(`"invalid hex digit"`), nil)
			}

			val = val*16 + digit
		}
		*v = val
	}

	return len(values), nil
}

