package binding

import (
	"fmt"
	"sync"
)

// stringFromSprintf creates a formatted string binding from multiple data items
type stringFromSprintf struct {
	base
	format string
	sources []DataItem
	mu sync.RWMutex
}

// NewSprintf creates a new String binding that formats multiple data items using fmt.Sprintf.
// The format string follows the same rules as fmt.Sprintf.
// The returned binding will update whenever any of the source bindings change.
// This binding is read-only.
//
// Example:
//   name := binding.NewString()
//   age := binding.NewInt()
//   formatted := binding.NewSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.5
func NewSprintf(format string, bindings ...DataItem) String {
	if len(bindings) == 0 {
		return NewString() // Return empty binding if no sources
	}

	s := &stringFromSprintf{
		format: format,
		sources: bindings,
	}

	// Listen to all source bindings
	for _, b := range bindings {
		if b != nil {
			b.AddListener(s)
		}
	}

	return s
}

func (s *stringFromSprintf) Get() (string, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		if source == nil {
			values[i] = nil
			continue
		}

		// Extract the actual value from each binding based on its type
		switch src := source.(type) {
		case String:
			if val, err := src.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = ""
			}
		case Int:
			if val, err := src.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = 0
			}
		case Float:
			if val, err := src.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = 0.0
			}
		case Bool:
			if val, err := src.Get(); err == nil {
				values[i] = val
			} else {
				values[i] = false
			}
		default:
			// For other types, try to get as generic DataItem
			// This won't work directly, but we handle the common cases above
			values[i] = nil
		}
	}

	return fmt.Sprintf(s.format, values...), nil
}

func (s *stringFromSprintf) Set(string) error {
	// Sprintf bindings are read-only
	return fmt.Errorf("sprintf bindings are read-only")
}

func (s *stringFromSprintf) DataChanged() {
	s.lock.RLock()
	defer s.lock.RUnlock()
	s.trigger()
}

