}

// StringToStringWithFormat creates a formatted String binding from another String binding.
// This is a convenience function that wraps a String binding with a format.
// If the format is "%s" (identity), it returns the original binding directly (no wrapping).
// Otherwise, it delegates to NewSprintf(format, str).
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str // Identity format - return original binding
	}
	return NewSprintf(format, str)
}

