// NewSprintf creates a new String binding that formats multiple data items using fmt.Sprintf.
// The format string follows the same rules as fmt.Sprintf.
// The returned binding will update whenever any of the source bindings change.
// This binding is read-only.
//
// Example:
//   name := binding.NewString()
//   age := binding.NewInt()
//   formatted := binding.NewSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.5
func NewSprintf(format string, bindings ...DataItem) String {
	if len(bindings) == 0 {
		return NewString() // Return empty binding if no sources
	}

	s := &stringFromSprintf{
		format: format,
		sources: bindings,
	}

	// Listen to all source bindings
	for _, b := range bindings {
		if b != nil {
			b.AddListener(s)
		}
	}

	return s
}
